import json

def unique_jsonl(text):
    seen = set()
    result = []
    for line in text.splitlines():
        if not line.strip():
            continue
        try:
            value = json.loads(line)
        except json.JSONDecodeError:
            raise ValueError(f"Invalid JSON: {line}")
        # Convert to a canonical form for comparison
        # For objects, sort keys; for arrays, keep order
        def canonical(obj):
            if isinstance(obj, dict):
                return tuple(sorted((k, canonical(v)) for k, v in obj.items()))
            elif isinstance(obj, list):
                return tuple(canonical(v) for v in obj)
            else:
                return obj
        key = canonical(value)
        if key not in seen:
            seen.add(key)
            result.append(line)
    return result

